int smallest_change(std::vector<int>& arr) {
    int n = arr.size();
    int change_needed = 0;

    // Iterate through the first half of the array
    for (int i = 0; i < n / 2; ++i) {
        // Compare the element at the current index with its corresponding element from the end
        if (arr[i] != arr[n - i - 1]) {
            // If they are not equal, increment the change needed
            ++change_needed;
        }
    }

    return change_needed;
}
