            # Calculate the new position to rotate the character
            new_position = (ord(c) - ord('a') + 2) % 26
            return chr(new_position + ord('a'))
        elif c.isupper():
            # Calculate the new position to rotate the character
            new_position = (ord(c) - ord('A') + 2) % 26
            return chr(new_position + ord('A'))
        else:
            return c

