def move_one_ball(arr):
    if not arr: 
        return True

    # Check if the array is already sorted in non-decreasing order
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False

    # Perform right shift operations
    n = len(arr)
    for _ in range(n):
        arr = arr[1:] + arr[:1]

    # Check if the array is sorted after the right shift operations
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False

    return True
