def reverse_delete(s, c):
    # Create a set of characters in c to avoid duplicates
    c_set = set(c)

    # Use a set to keep track of characters that should be deleted
    to_delete = set()

    # Iterate through each character in s
    for char in s:
        # If the character is in c, add it to to_delete
        if char in c_set:
            to_delete.add(char)

    # If to_delete is empty, the result string is not a palindrome
    if len(to_delete) == 0:
        return ('', False)

    # Find the last occurrence of each character in s to exclude
    # This is done by sorting the list of characters and adding each character to a set
    last_occurrences = sorted(set(s))

    # Check if any character in c_set has been excluded in the last occurrences
    for char in c_set:
        if char not in last_occurrences:
            return ('', False)

    # If no characters in c_set have been excluded, the result string is a palindrome
    return (''.join(s), True)

# Test cases
print(reverse_delete("abcde", "ae"))  # ('bcd', False)
print(reverse_delete("abcdef", "b"))  # ('acdef', False)
print(reverse_delete("abcdedcba", "ab")) # ('cdedc', True)
```

