class Solution:
    def bucketweaver(self, grid, capacity):
        n, m = len(grid), len(grid[0])
        queue = deque([(0, 0)])  # BFS starting from the top-left corner (0, 0)
        visited = set([(0, 0)])  # Set to keep track of visited cells
        total = 0
        max_capacity = capacity

        while queue:
            x, y = queue.popleft()

            for nx, ny in [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]:
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                    queue.append((nx, ny))
                    visited.add((nx, ny))
                    total += 1
                    if grid[nx][ny] == 1:
                        grid[nx][ny] = 0
                        max_capacity -= 1
                        if max_capacity == 0:
                            return total
        return 0
