class Solution:
    def fill_wells(self, grid: List[List[int]], capacity: int) -> int:
        res = 0
        for r, row in enumerate(grid):
            for c, v in enumerate(row):
                if v == 1:
                    if c + 1 < len(row) and grid[r][c + 1] == 1:
                        res += math.ceil((capacity - v) / (grid[r][c] + grid[r][c + 1]))
