class Solution {
private:
    int N, K;
    bool memo[101][101][101];

    // Helper function to calculate the minimum path
    bool minPathHelper(int x, int y, int k, int path) {
        if (x < 0 || y < 0 || x >= N || y >= N) return false;
        if (k == 0) return true;

        if (memo[x][y][k] != -1) return memo[x][y][k];

        // Try moving to the adjacent cells
        bool left = minPathHelper(x - 1, y, k - 1, path + grid[x][y]);
        bool right = minPathHelper(x + 1, y, k - 1, path + grid[x][y]);
        bool up = minPathHelper(x, y - 1, k - 1, path + grid[x][y]);
        bool down = minPathHelper(x, y + 1, k - 1, path + grid[x][y]);

        if (left || right || up || down) {
            memo[x][y][k] = path;
            return true;
        }

        memo[x][y][k] = -1;
        return false;
    }

public:
    vector<int> kSmallestPath(vector<vector<int>>& grid, int k) {
        this->N = grid.size();
        this->K = k;
        memset(memo, -1, sizeof(memo));

        vector<int> ans;
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (minPathHelper(i, j, k - 1, grid[i][j])) {
                    ans.push_back(grid[i][j]);
                }
            }
        }

        return ans;
    }
};
```

