def do_algebra(operator, operand):
    # Initialize the result to the first operand
    result = operand[0]

    # Iterate over the operator list and perform each operation
    for op, val in zip(operator, operand[1:]):
        if op == '+':
            result += val
        elif op == '-':
            result -= val
        elif op == '*':
            result *= val
        elif op == '//':
            result //= val
        elif op == '**':
            result **= val
        else:
            raise ValueError(f"Unsupported operation: {op}")

    return result
